# ==============================================================================# 044_AI_DECISION_ENGINE.py# ==============================================================================import sqlite3from pathlib import Pathfrom datetime import datetimeROOT = Path(__file__).resolve().parentDB = ROOT / "MISSION_CONTROL" / "database" / "mission_control.db"conn = sqlite3.connect(DB, timeout=30)conn.row_factory = sqlite3.Rowcur = conn.cursor()

cur.execute("PRAGMA journal_mode=WAL")
cur.execute("PRAGMA synchronous=NORMAL")
cur.execute("PRAGMA busy_timeout=30000")# ==============================================================================# DECISION TABLE# ==============================================================================cur.execute("""CREATE TABLE IF NOT EXISTS ai_decisions(    id INTEGER PRIMARY KEY AUTOINCREMENT,    created_at TEXT,    category TEXT,    severity TEXT,    decision TEXT,    recommendation TEXT,    source TEXT,    status TEXT)""")conn.commit()# ==============================================================================# COLETA# ==============================================================================cur.execute("""SELECT healthFROM runtime_monitorORDER BY id DESCLIMIT 1""")r = cur.fetchone()health = r["health"] if r else 0cur.execute("""SELECT COUNT(*)FROM services""")services = cur.fetchone()[0]cur.execute("""SELECT COUNT(*)FROM scheduler""")scheduler = cur.fetchone()[0]cur.execute("""SELECT COUNT(*)FROM command_busWHERE status='PENDING'""")pending_commands = cur.fetchone()[0]cur.execute("""SELECT COUNT(*)FROM task_queueWHERE status='PENDING'""")pending_tasks = cur.fetchone()[0]# ==============================================================================# MOTOR DE DECISÃƒO# ==============================================================================decisions = []if health >= 95:    decisions.append(        (            "HEALTH",            "INFO",            "SYSTEM_STABLE",            "Nenhuma aÃ§Ã£o necessÃ¡ria.",            "Runtime Monitor",            "OPEN"        )    )else:    decisions.append(        (            "HEALTH",            "CRITICAL",            "SYSTEM_DEGRADED",            "Executar Health Check imediatamente.",            "Runtime Monitor",            "OPEN"        )    )if pending_commands == 0:    decisions.append(        (            "COMMAND_BUS",            "INFO",            "COMMAND_QUEUE_EMPTY",            "Fila totalmente processada.",            "Command Processor",            "OPEN"        )    )else:    decisions.append(        (            "COMMAND_BUS",            "WARNING",            "COMMAND_QUEUE_PENDING",            "Processar comandos pendentes.",            "Command Processor",            "OPEN"        )    )if pending_tasks == 0:    decisions.append(        (            "TASK_QUEUE",            "INFO",            "TASK_QUEUE_EMPTY",            "Nenhuma tarefa aguardando execuÃ§Ã£o.",            "Task Executor",            "OPEN"        )    )else:    decisions.append(        (            "TASK_QUEUE",            "WARNING",            "TASK_QUEUE_PENDING",            "Executar Task Executor.",            "Task Queue",            "OPEN"        )    )if scheduler > 0:    decisions.append(        (            "SCHEDULER",            "INFO",            "SCHEDULER_ACTIVE",            f"{scheduler} tarefas agendadas.",            "Scheduler",            "OPEN"        )    )if services >= 25:    decisions.append(        (            "SERVICES",            "INFO",            "ALL_CORE_SERVICES_AVAILABLE",            f"{services} serviÃ§os registrados.",            "Service Discovery",            "OPEN"        )    )# ==============================================================================# GRAVA# ==============================================================================for item in decisions:    cur.execute("""    INSERT INTO ai_decisions(        created_at,        category,        severity,        decision,        recommendation,        source,        status    )    VALUES(?,?,?,?,?,?,?)    """,(        datetime.now().isoformat(),        item[0],        item[1],        item[2],        item[3],        item[4],        item[5]    ))conn.commit()# ==============================================================================# OUTPUT# ==============================================================================print("="*80)print("AI DECISION ENGINE")print("="*80)cur.execute("""SELECTcategory,severity,decision,recommendationFROM ai_decisionsORDER BY id DESCLIMIT 20""")rows = cur.fetchall()for row in rows:    print(        f"{row['severity']:<9}"        f"{row['category']:<15}"        f"{row['decision']:<32}"        f"{row['recommendation']}"    )print("="*80)cur.execute("SELECT COUNT(*) FROM ai_decisions")print("DECISÃ•ES REGISTRADAS:", cur.fetchone()[0])print("="*80)conn.close()

